import test from 'node:test';
import assert from 'node:assert/strict';
import { generatePreset, prepareHostCommand, createHostBridge, nativeFacetPlane, normalizeTransform } from '../src/index.js';
import { cubeDocument } from './fixtures.mjs';
// Explicit contract double: not the upstream application's full reducer / CI.
const domain = { resolveFacet: (f, { stock }) => ({ ...f, plane: nativeFacetPlane(f, stock) }), createReplaceDocumentCommand: document => ({ type: 'document/replace', document }) };
const input = () => ({ component: generatePreset(), transform: normalizeTransform({ translation: [0, 0, .045] }), instanceId: 'new' });
test('host command is atomic and replacement remains in original group slot', () => { const first = prepareHostCommand({ document: cubeDocument(), ...input(), domain }), withP = prepareHostCommand({ document: first.document, component: generatePreset({ part: 'pavilion' }), transform: { translation: [0, 0, -.045] }, instanceId: 'p', domain }), replacement = prepareHostCommand({ document: withP.document, ...input(), replaceInstanceId: 'new', domain }); assert.equal(replacement.command.type, 'document/replace'); assert.equal(replacement.document.facets.length, 57); assert.equal(replacement.document.metadata.componentInstances[0].id, 'new'); assert.equal(replacement.document.facets[0].metadata.componentInstanceId, 'new'); });
test('bridge commits once after impact confirmation', async () => { let calls = 0; const bridge = createHostBridge({ domain, getDocument: cubeDocument, getRevision: () => 3, canApply: () => true, analyzeImpact: async () => ({ canApply: true, requiresConfirmation: true }), confirmImpact: async () => true, dispatch: () => calls++ }); const r = await bridge.apply(input()); assert.equal(r.applied, true); assert.equal(calls, 1); });
test('bridge read-only and impact rejection cannot dispatch', async () => { for (const permitted of [false, true]) {
    let calls = 0;
    const bridge = createHostBridge({ domain, getDocument: cubeDocument, getRevision: () => 3, canApply: () => permitted, analyzeImpact: async () => ({ canApply: false }), dispatch: () => calls++ });
    await assert.rejects(() => bridge.apply(input()));
    assert.equal(calls, 0);
} });
test('bridge cancelled confirmation leaves host unchanged', async () => { let calls = 0; const bridge = createHostBridge({ domain, getDocument: cubeDocument, getRevision: () => 3, canApply: () => true, analyzeImpact: async () => ({ canApply: true, requiresConfirmation: true }), confirmImpact: async () => false, dispatch: () => calls++ }); const r = await bridge.apply(input()); assert.equal(r.cancelled, true); assert.equal(calls, 0); });
test('bridge rejects revision changes while awaiting confirmation', async () => { let rev = 3, calls = 0; const bridge = createHostBridge({ domain, getDocument: cubeDocument, getRevision: () => rev, canApply: () => true, analyzeImpact: async () => ({ canApply: true, requiresConfirmation: true }), confirmImpact: async () => { rev++; return true; }, dispatch: () => calls++ }); await assert.rejects(() => bridge.apply(input())); assert.equal(calls, 0); });
test('bridge blocks concurrent apply and unlocks after completion', async () => { let release, calls = 0; const gate = new Promise(r => release = r), bridge = createHostBridge({ domain, getDocument: cubeDocument, getRevision: () => 3, canApply: () => true, analyzeImpact: async () => { await gate; return { canApply: true }; }, dispatch: () => calls++ }); const first = bridge.apply(input()); await assert.rejects(() => bridge.apply(input())); release(); await first; await bridge.apply(input()); assert.equal(calls, 2); });
test('host update rejects vanished component and new ID collisions', () => { assert.throws(() => prepareHostCommand({ document: cubeDocument(), ...input(), replaceInstanceId: 'missing', domain }), /不存在/); const first = prepareHostCommand({ document: cubeDocument(), ...input(), domain }); assert.throws(() => prepareHostCommand({ document: first.document, ...input(), domain }), /冲突/); });
